  "ai_overview": {
    "text_blocks": [
      {
        "type": "paragraph",
        "snippet": "The primary symptom of typhoid fever in adults is a prolonged, gradually climbing fever that can reach up to 104°F (40°C).",
        "snippet_highlighted_words": [
          "a prolonged, gradually climbing fever that can reach up to 104°F (40°C)"
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "paragraph",
        "snippet": "According to the Cleveland Clinic, typhoid symptoms usually appear one to three weeks after exposure to Salmonella typhi bacteria and develop progressively.",
        "snippet_links": [
          {
            "text": "Cleveland Clinic",
            "link": "https://my.clevelandclinic.org/health/diseases/17730-typhoid-fever"
          }
        ],
        "reference_indexes": [
          1,
          2
        ]
      },
      {
        "type": "heading",
        "snippet": "Common Early Symptoms"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Steadily rising fever: A temperature that starts low and increases each day, often peaking in the evening."
          },
          {
            "snippet": "Headache: A persistent, dull, or intense head pain."
          },
          {
            "snippet": "Fatigue and weakness: A deep sense of exhaustion or lethargy."
          },
          {
            "snippet": "Stomach pain: Aching or discomfort in the abdomen."
          },
          {
            "snippet": "Loss of appetite: A lack of interest in eating, leading to weight loss."
          },
          {
            "snippet": "Constipation or diarrhea: Constipation is notably more common in adults during early illness, whereas children more frequently experience diarrhea."
          },
          {
            "snippet": "Aches and chills: Body aches, muscle pain, and chills."
          },
          {
            "snippet": "Dry cough: A mild, non-productive cough in the early stages."
          }
        ],
        "reference_indexes": [
          1,
          3,
          4,
          5,
          6
        ]
      },
      {
        "type": "heading",
        "snippet": "Progressed and Classic Signs"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Rose spots: A faint, flat, salmon-colored or light-pink rash that can appear on the chest and abdomen in about one-third of patients (though harder to see on darker skin tones)."
          },
          {
            "snippet": "Relative bradycardia: A heart rate that stays relatively slow or low compared to how high the fever is."
          },
          {
            "snippet": "Enlarged organs: Swelling of the liver or spleen (hepatosplenomegaly) detected during a clinical exam."
          }
        ],
        "reference_indexes": [
          0,
          1,
          6
        ]
      },
      {
        "type": "heading",
        "snippet": "Severe Warning Signs (Untreated Cases)"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Delirium or confusion: A \"foggy\" mental state, extreme restlessness, or hallucinations."
          },
          {
            "snippet": "Severe abdominal pain: Triggered by dangerous complications like internal bleeding or holes (perforation) in the intestines, usually by the third week."
          }
        ],
        "reference_indexes": [
          1
        ]
      },
      {
        "type": "paragraph",
        "snippet": "You can review official guidance and resources from the Centers for Disease Control and Prevention regarding.",
        "snippet_links": [
          {
            "text": "Centers for Disease Control and Prevention",
            "link": "https://www.cdc.gov/typhoid-fever/signs-symptoms/index.html"
          }
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "paragraph",
        "snippet": "If you or someone you know is experiencing symptoms, let me know:"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "How many days the fever has lasted"
          },
          {
            "snippet": "Whether there is severe stomach pain or confusion"
          }
        ]
      },
      {
